def next_kept(text, i):
    # Walk left from index i to the next character that survives the backspaces.
    # Returns its index, or -1 if nothing before i survives.
    skip = 0                     # backspaces seen but not yet applied
    while i >= 0:
        if text[i] == "#":
            skip += 1
        elif skip > 0:
            skip -= 1            # this character is deleted by a later '#'
        else:
            return i
        i -= 1
    return -1

def solution(s, t):
    # Compare from the end: a '#' only affects characters to its left,
    # so reading right-to-left tells us immediately what is deleted. O(1) space.
    i = next_kept(s, len(s) - 1)
    j = next_kept(t, len(t) - 1)
    while i >= 0 and j >= 0:
        if s[i] != t[j]:
            return False
        i = next_kept(s, i - 1)
        j = next_kept(t, j - 1)
    return i < 0 and j < 0       # equal only if both run out together

