def final_text(log):
    # Replay the edits with a list used as a stack. O(n) time, O(n) extra space.
    kept = []
    for ch in log:
        if ch == "#":
            if kept:             # backspace on an empty box does nothing
                kept.pop()
        else:
            kept.append(ch)
    return "".join(kept)

def solution(s, t):
    return final_text(s) == final_text(t)
